import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void batch_norm_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int64_t* __restrict__ num_batches_tracked,
    int64_t channels,
    int64_t elements_per_channel,
    bool training,
    float momentum,
    float eps
) {
    const int64_t c = static_cast<int64_t>(blockIdx.x);
    if (c >= channels) {
        return;
    }

    __shared__ float shared_sum[256];
    __shared__ float shared_sq_sum[256];
    const int tid = threadIdx.x;

    float mean;
    float variance;

    if (training) {
        float sum = 0.0f;
        float sq_sum = 0.0f;

        for (int64_t i = tid; i < elements_per_channel; i += blockDim.x) {
            const int64_t offset = i * channels + c;
            const float v = x[offset];
            sum += v;
            sq_sum += v * v;
        }

        shared_sum[tid] = sum;
        shared_sq_sum[tid] = sq_sum;
        __syncthreads();

        for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
            if (tid < stride) {
                shared_sum[tid] += shared_sum[tid + stride];
                shared_sq_sum[tid] += shared_sq_sum[tid + stride];
            }
            __syncthreads();
        }

        if (tid == 0) {
            mean = shared_sum[0] / static_cast<float>(elements_per_channel);
            variance =
                shared_sq_sum[0] / static_cast<float>(elements_per_channel)
                - mean * mean;

            if (variance < 0.0f) {
                variance = 0.0f;
            }

            running_mean[c] =
                (1.0f - momentum) * running_mean[c] + momentum * mean;

            float unbiased_variance = variance;
            if (elements_per_channel > 1) {
                unbiased_variance =
                    variance *
                    (static_cast<float>(elements_per_channel) /
                     static_cast<float>(elements_per_channel - 1));
            }

            running_var[c] =
                (1.0f - momentum) * running_var[c]
                + momentum * unbiased_variance;

            if (c == 0 && num_batches_tracked != nullptr) {
                *num_batches_tracked += 1;
            }
        }

        __syncthreads();
    }

    if (!training) {
        mean = running_mean[c];
        variance = running_var[c];
    }

    const float inv_std = rsqrtf(variance + eps);
    const float gamma = weight[c];
    const float beta = bias[c];

    for (int64_t i = tid; i < elements_per_channel; i += blockDim.x) {
        const int64_t offset = i * channels + c;
        const float normalized = (x[offset] - mean) * inv_std;
        y[offset] = normalized * gamma + beta;
    }
}
void batch_norm_launcher(
    const float* x,
    float* y,
    const float* weight,
    const float* bias,
    float* running_mean,
    float* running_var,
    int64_t* num_batches_tracked,
    int64_t channels,
    int64_t elements_per_channel,
    bool training,
    float momentum,
    float eps,
    cudaStream_t stream
) {
    const dim3 grid(static_cast<unsigned int>(channels));
    const dim3 block(256);
    batch_norm_kernel<<<grid, block, 0, stream>>>(
        x,
        y,
        weight,
        bias,
        running_mean,
        running_var,
        num_batches_tracked,
        channels,
        elements_per_channel,
        training,
        momentum,
        eps
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}
"""


_cpp_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

void batch_norm_launcher(
    const float* x,
    float* y,
    const float* weight,
    const float* bias,
    float* running_mean,
    float* running_var,
    int64_t* num_batches_tracked,
    int64_t channels,
    int64_t elements_per_channel,
    bool training,
    float momentum,
    float eps,
    cudaStream_t stream
);

torch::Tensor bn_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor num_batches_tracked,
    bool training,
    float momentum,
    float eps
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be a 4D tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "parameters must be CUDA tensors");
    TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(),
                "running statistics must be CUDA tensors");

    const auto n = x.size(0);
    const auto c = x.size(1);
    const auto h = x.size(2);
    const auto w = x.size(3);

    auto y = torch::empty_like(x);

    const int64_t elements_per_channel = n * h * w;
    c10::cuda::CUDAGuard device_guard(x.device());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream(x.device().index());

    batch_norm_launcher(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        num_batches_tracked.numel()
            ? num_batches_tracked.data_ptr<int64_t>()
            : nullptr,
        c,
        elements_per_channel,
        training,
        momentum,
        eps,
        stream
    );
    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("bn_forward", &bn_forward, "Custom CUDA BatchNorm2d forward");
}
"""


_bn_cuda = load_inline(
    name="custom_batch_norm_cuda",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=None,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_features: int) -> None:
        super().__init__()

        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer(
            "num_batches_tracked",
            torch.tensor(0, dtype=torch.long),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _bn_cuda.bn_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.num_batches_tracked,
            self.training,
            self.momentum,
            self.eps,
        )

