#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void batch_norm_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int64_t* __restrict__ num_batches_tracked,
    int64_t channels,
    int64_t elements_per_channel,
    int64_t spatial_per_batch,
    bool training,
    float momentum,
) {
    const int64_t c = static_cast<int64_t>(blockIdx.x);
    if (c >= channels) {
        return;
    }

    __shared__ float shared_sum[256];
    __shared__ float shared_sq_sum[256];
    __shared__ float shared_mean;
    __shared__ float shared_variance;
    const int tid = threadIdx.x;
    float mean;
    float variance;
    if (training) {
        float sum = 0.0f;
        float sq_sum = 0.0f;

        for (int64_t i = tid; i < elements_per_channel; i += blockDim.x) {
            const int64_t batch = i / spatial_per_batch;
            const int64_t spatial = i % spatial_per_batch;
            const int64_t offset =
                batch * channels * spatial_per_batch
                + c * spatial_per_batch + spatial;
            const float v = x[offset];

        shared_sum[tid] = sum;
        shared_sq_sum[tid] = sq_sum;
        __syncthreads();

        for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
            if (tid < stride) {
                shared_sum[tid] += shared_sum[tid + stride];
                shared_sq_sum[tid] += shared_sq_sum[tid + stride];
            }
            __syncthreads();
        }

        if (tid == 0) {
            const float mean_value =
                shared_sum[0] / static_cast<float>(elements_per_channel);
            float variance_value =
                shared_sq_sum[0] / static_cast<float>(elements_per_channel)
                - mean_value * mean_value;
            if (variance_value < 0.0f) {
                variance_value = 0.0f;
            }
            shared_mean = mean_value;
            shared_variance = variance_value;
            running_mean[c] =
                (1.0f - momentum) * running_mean[c]
                + momentum * mean_value;
            float unbiased_variance = variance_value;
            if (elements_per_channel > 1) {
                unbiased_variance =
                    variance_value *
                    (static_cast<float>(elements_per_channel) /
                     static_cast<float>(elements_per_channel - 1));
            }
            running_var[c] =
